from typing import List, Optional
from pydantic import BaseModel, Field

class SubTopicQuery(BaseModel):
    """Specific sub-topic angle and search query generated by planner."""
    angle: str = Field(description="Subtopic angle (e.g. 'Technological Maturity', 'Cost & Economics', 'Regulatory Hurdles')")
    search_query: str = Field(description="Optimized search engine query")
    rationale: str = Field(description="Why this query is essential for the research topic")

class ResearchPlan(BaseModel):
    """Structured multi-step research plan formulated by Planner Agent."""
    topic: str = Field(description="Original user topic or question")
    core_objective: str = Field(description="Core question or research hypothesis to address")
    key_dimensions: List[str] = Field(
        default_factory=list,
        description="Key conceptual dimensions to explore"
    )
    sub_queries: List[SubTopicQuery] = Field(
        default_factory=list,
        description="Targeted queries for web search and document retrieval"
    )
    planned_report_sections: List[str] = Field(
        default_factory=list,
        description="Proposed sections for final research report"
    )
